              <ColumnShown column="contact"><td data-testid="person-contact">{p.contact ?? ''}</td></ColumnShown>
              <td data-testid="person-tags">{p.tags.join(', ')}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
